\documentclass[tikz, border=5mm]{standalone}
\usepackage{pgfplots} 
\usepackage{hyperref}
\usepackage{graphicx}
\usepackage{amsmath}
\usepackage{cancel}
\usepackage[utf8]{inputenc}
\usepackage[T1]{fontenc}
\usepackage{makecell}
\usetikzlibrary{calc} 
\usepackage{tkz-euclide}
\usetkzobj{all}

\begin{document}
\pagestyle{empty}

\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}
\definecolor{blue}{rgb}{0.173,0.447,0.682}	

\begin{tikzpicture}[scale=1.2]

% n      - modulus
% layers - number of layers (rings)
% spoke  - selected class

\def\n{5}
\def\layers{3}
\def\spoke{3}

% ---
\tkzDefPoints{0/0/O, 0/0.65/X}

% Layers
\foreach \j in {0,...,\layers} {
	\tkzDefPointsBy[homothety=center O ratio {1.5+0.6*\j}](X){Y} 
	\tkzDrawCircle[color=deepskyblue!50, line width=10pt, opacity=0.3](O,Y)
}

% Spoke
\tkzDefPointBy[rotation = center O angle {-360/\n*(\spoke-0.35)}](X) \tkzGetPoint{C1}
\tkzDefPointsBy[homothety=center O ratio 3.7](C1){C1}
\tkzDefPointBy[rotation = center O angle {-360/\n*(\spoke+0.35)}](X) \tkzGetPoint{C2}
\tkzDefPointsBy[homothety=center O ratio 3.7](C2){C2}
\tkzDrawSector[draw=none, fill=orangepeel!50, fill opacity=0.5](O,C2)(C1)

% Circle
\tkzDrawCircle[color=black, very thick, fill=deepskyblue!20, fill opacity=1](O,X)
\node[] at (O) {$\text{mod}\:\n$};

% Small spokes
\foreach \i in {1,...,\n} {
    \tkzDefPointBy[rotation = center O angle {-360/\n*(\i-1)}](X) \tkzGetPoint{A}
    \tkzDefPointsBy[homothety=center O ratio 1.2](A){B} 
    \tkzDefPointsBy[homothety=center O ratio 1.5](A){C} 
    \tkzDrawSegment[very thick, black](A,B) 
}

% Numbers on Layers
\foreach \j in {0,...,\layers} {
	\foreach \i in {1,...,\n} {
    	\tkzDefPointBy[rotation = center O angle {-360/\n*(\i-1)}](X) \tkzGetPoint{A}
    	\pgfmathtruncatemacro\markC{\j*\n+(\i-1)}
    	\tkzDefPointsBy[homothety=center O ratio {1.5+0.6*\j}](A){C} 
    	\node[] at (C) {\footnotesize \markC};
	}
}

% Dots
\foreach \i in {1,...,\n} {
    \tkzDefPointBy[rotation = center O angle {-360/\n*(\i-1)}](X) \tkzGetPoint{A}
    \tkzDefPointsBy[homothety=center O ratio {1.5+0.6*(\layers+1)}](A){C} 
    \tkzDefPointsBy[homothety=center O ratio {1.5+0.6*(\layers+1)+0.2}](A){D} 
    \tkzDefPointsBy[homothety=center O ratio {1.5+0.6*(\layers+1)+0.4}](A){E} 
    \node[circle, draw=none, fill=black, inner sep=0.5pt] at (C) {};
	\node[circle, draw=none, fill=black, inner sep=0.5pt] at (D) {};
	\node[circle, draw=none, fill=black, inner sep=0.5pt] at (E) {};	
}

\end{tikzpicture}
\end{document}

